/** Thrown when work is handed to a member who is currently suspended. */
export class MemberSuspendedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly memberId: MemberId) {
    super(`Member ${memberId} is suspended`);
    this.name = "MemberSuspendedError";
  }
}

/**
 * Locks a member out without freeing their seat or touching their role. A
 * suspension is idempotent (suspending an already-suspended member is a
 * no-op) and subject to the same guards as removal: it cannot target self or
 * a higher role, and it cannot leave the organization without an active
 * owner.
 */
export async function suspendMember(
  actor: Actor,
  input: SuspendMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = await memberRepo.findMemberById(input.orgId, input.memberId);
  if (!member || member.archivedAt !== null) {
    throw new NotFoundError("Member", input.memberId);
  }
  assertCan(actor, "member:remove", memberResource(member));

  if (member.status === "suspended") {
    return member;
  }

  if (member.userId === actor.userId) {
    throw new Error("Cannot suspend yourself");
  }
  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(`A ${actor.role} cannot suspend a ${member.role}`);
  }

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const suspended = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: suspended.id,
    userId: suspended.userId,
  });

  return suspended;
}

